/**
 * @param {string} s
 * @param {string} t
 * @return {number}
 */
var numDistinct = function(s, t) {
    let res = 0;

    const dfs = (i, j) => {
        if (i >= s.length || j >= t.length) {
            if (j >= t.length) {
                res++;
            }
            return;
        }

        if (s[i] === t[j]) {
            dfs(i + 1, j + 1);
        }
        dfs(i + 1, j);
    };
    dfs(0, 0);

    return res;
};

/**
 * @param {string} s
 * @param {string} t
 * @return {number}
 */
var numDistinct = function(s, t) {
    const dp = Array.from({ length: s.length }, () => Array(t.length).fill(-1));

    const dfs = (i, j) => {
        if (j === t.length) return 1;
        if (i === s.length) return 0;
        if (dp[i][j] !== -1) return dp[i][j];

        let take = 0;
        let skip = 0;

        if (s[i] === t[j]) {
            take = dfs(i + 1, j + 1);
        }
        skip = dfs(i + 1, j);

        dp[i][j] = take + skip;
        return dp[i][j];
    };

    return dfs(0, 0);
};

/**
 * @param {string} s
 * @param {string} t
 * @return {number}
 */
var numDistinct = function(s, t) {
    const memo = new Map();

    const dfs = (cur, lookup) => {
        const key = cur + ':' + lookup;
        if (memo.has(key)) return memo.get(key);

        if (lookup === t.length) {
            memo.set(key, 1);
            return 1;
        }
        if (cur === s.length) {
            memo.set(key, 0);
            return 0;
        }

        const res = dfs(cur + 1, lookup) +
            (s[cur] === t[lookup] ? dfs(cur + 1, lookup + 1) : 0);

        memo.set(key, res);
        return res;
    };
    return dfs(0, 0);
};

/**
 * @param {string} s
 * @param {string} t
 * @return {number}
 */
var numDistinct = function(s, t) {
    const dp = Array(t.length + 1).fill(0);
    dp[0] = 1;

    for (const char of s) {
        for (let j = t.length - 1; j >= 0; j--) {
            if (char === t[j]) {
                dp[j + 1] += dp[j];
            }
        }
    }

    return dp[t.length];
};
